package org.eclipse.myplugin;

import org.eclipse.core.runtime.Platform;
import org.eclipse.jface.util.SafeRunnable;

// Dummy classes/interfaces for compilation context
interface CoreException {}
interface IConfigurationElement {}
interface IBaseLabelProvider {}
interface ILabelDecorator {}
class NLS { public static String bind(String message, Object... args) { return message; } }
class WorkbenchMessages { public static String DecoratorManager_ErrorActivatingDecorator = "Error activating decorator {0}"; }

// Dummy for a class that also has a 'run' method but is not Platform
class SomeOtherClass {
    public static void run(java.lang.Runnable runnable) { /* some other run method */ }
}

public class MyClass {
    private String name = "Test";

    public String getName() { return name; }

    public ILabelDecorator getDecorator() throws CoreException {
        ILabelDecorator decorator = null;
        if (decorator == null) {
            // This should NOT be matched because it's SomeOtherClass.run()
            SomeOtherClass.run(
                    new SafeRunnable(NLS.bind(WorkbenchMessages.DecoratorManager_ErrorActivatingDecorator, getName())) {
                        @Override
                        public void run() {
                            System.out.println("Running SomeOtherClass.run");
                        }
                    });
        }
        return decorator;
    }
}

// Minimal dummy Platform class for compilation (not used in this negative example, but might be needed for a real project)
class Platform {
    public static void run(java.lang.Runnable runnable) { /* dummy */ }
}
